    "id": "rtm-0036",
    "record_type": "recipe",
    "title": "Stollen tradicional alemán",
    "origin": "Documento aportado · Versión normalizada",
    "author": "",
    "type": "Pan dulce",
    "family": "Masas, panes y bollería",
    "servings": "2 piezas",
    "time": "24 h de reposo + fermentaciones + 25 min de horno",
    "difficulty": "Elaborada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "Para el mazapán: 150 g de almendra molida; 120 g de azúcar glas; 30 g de clara de huevo.",
      "Para la masa: 250 g de fruta confitada (naranja, limón y pasas); 50 g de ron; 425 g de harina de fuerza; 75 g de azúcar; 9 g de sal; 25 g de levadura fresca; 5 g de especias (canela, cardamomo, clavo y nuez moscada); 1 huevo; 150 g de leche; 150 g de mantequilla a temperatura ambiente.",
      "Para el acabado: mantequilla derretida y azúcar glas abundante."
    ],
    "steps": [
      "Prepara el mazapán mezclando almendra, azúcar glas y clara. Forma un cilindro, envuelve en film y deja 24 h en la nevera.",
      "Macera la fruta con el ron unas horas, mejor toda la noche.",
      "Mezcla harina, azúcar, sal, levadura, especias, huevo y leche; incorpora poco a poco la mantequilla.",
      "Amasa unos 10 min hasta obtener una masa lisa y elástica e incorpora la fruta macerada.",
      "Deja fermentar hasta doblar el volumen.",
      "Divide en dos piezas y forma una bola con cada una.",
      "Estira cada pieza en óvalo, coloca el cilindro de mazapán ligeramente desplazado del centro y dobla la masa con la forma asimétrica del Stollen.",
      "Deja fermentar de nuevo hasta que casi doble su volumen.",
      "Hornea a 170 °C durante 25 min; las piezas grandes pueden necesitar 35-45 min.",
      "Nada más salir, pinta con mantequilla derretida y cubre con azúcar glas; al enfriar, vuelve a cubrir generosamente."
    ],
    "presentation": "Sirve cortado en rebanadas finas una vez frío; la fuente recomienda dejarlo reposar antes de consumirlo.",
    "tips": "Conserva envuelto en papel de horno y después film o bolsa, dentro de caja metálica. La fuente indica 3-4 semanas y mejora con el reposo. Variante de la fuente: sustituir 50 g de leche por nata, añadir ralladura de limón y naranja, 50 g de almendra laminada tostada y esperar una semana antes de cortarlo.",
