    "status": "Pendiente de hacer",
    "ingredients": [
      "Para el lomo: 1,2 kg aprox. de cinta de lomo fresca; 150 g de ciruelas pasas sin hueso; 100 g de nueces; 100 g de higos secos; 100 g de coñac; sal; pimienta; film transparente; papel de aluminio.",
      "Para la salsa: 50 g de mantequilla; 70 g de aceite; 500 g de cebolla; 250 g de higos secos; coñac de la maceración; 400 g de cava semiseco; 2 pastillas de caldo de carne o sal y pimienta; 200 g de agua."
    ],
    "steps": [
      "Haz agujeros grandes por el contorno y los extremos del lomo.",
      "Trocea las ciruelas a velocidad 2; la fuente no especifica el tiempo.",
      "Divide las nueces en cuatro.",
      "Escurre los higos macerados y reserva el coñac.",
      "Retira el rabito de los higos y córtalos en cuatro.",
      "Rellena los agujeros del lomo alternando ciruela, nuez e higo. Presiona bien el relleno.",
      "Salpimienta el lomo.",
      "Envuélvelo firmemente en dos capas de film transparente y después en una de papel de aluminio. Colócalo en el Varoma.",
      "Trocea la cebolla 5 s · velocidad 3½ y reserva.",
      "Coloca la mariposa. Añade mantequilla, aceite y cebolla y cocina 15 min · Varoma · velocidad 1.",
      "Incorpora los higos, el coñac reservado, el cava, las pastillas de caldo o sazón y el agua.",
      "Coloca el Varoma en su posición y programa 40 min · Varoma · velocidad 1.",
      "Abre con precaución. Desenvuelve el lomo y pínchalo ligeramente para que sus jugos caigan al vaso.",
      "Retira el Varoma y la mariposa.",
      "Comprueba la sazón y la consistencia de la salsa. Si admite más líquido, añade un poco de agua.",
      "Corta el lomo en rodajas finas."
    ],
    "presentation": "Coloca las rodajas en una fuente y sirve la salsa muy caliente aparte. Opcionalmente cocina 200 g de higos y 200 g de ciruelas en el Varoma junto con la carne.",
    "tips": "Comprueba que el lomo cabe en el Varoma. Presiona bien relleno y envoltorio. Abre con precaución. Para salsa fina, retira los higos, tritura y reincorpóralos. Conservación pendiente de confirmar.",
