    "record_type": "recipe",
    "title": "Donuts rellenos de crema de cacao",
    "origin": "Fresa y Pimienta · Página web recuperada desde Evernote · No indicadas",
    "author": "",
    "type": "Donut horneado",
    "family": "Pastelería y repostería",
    "servings": "No indicadas",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "220 g de harina.",
      "150 g de azúcar.",
      "10 g de levadura en polvo.",
      "1 cucharadita de esencia de vainilla.",
      "180 g de leche + un cucharadita de vinagre.",
      "2 huevos.",
      "1 pizca de sal.",
      "20 g de mantequilla fundida.",
      "Crema de Cacao (yo he utilizado Nutella).",
      "Azúcar glasé para rebozar los donuts."
    ],
    "steps": [
      "En un bowl disponemos la harina, el azúcar, la levadura en polvo y la sal, mezclamos y reservamos.",
      "En otro bowl preparamos la mezcla líquida: batimos dos huevos, añadimos la esencia de vainilla, la mantequilla fundida y la leche (previamente la hemos mezclado con el vinagre y la hemos dejado reposar durante 5 min).",
      "Incorporamos la mezcla de ingredientes líquidos a los secos y batimos con una varilla manual hasta obtener una masa homogénea.",
      "Introducimos la masa en un recipiente, que debe tener el formato de los “donuts”, rellanando ¾ partes del mismo. Introducimos en el horno precalentado a 180 °C durante 9 min.",
      "Retiramos del horno y dejamos los “donuts” dentro del recipiente durante 5 min, transcurrido este tiempo ya podemos desmoldarlos y ponerlos sobre una rejilla hasta que se hayan enfriado.",
      "Con ayuda de una jeringuilla, o una boquilla de rellenar, cogemos la crema de cacao y vamos haciendo pequeñas inserciones en la parte inferior del “donut”.",
      "Finalmente espolvoreamos con azúcar glasé."
    ],
