    "title": "Dürüm turco de pollo",
    "origin": "Las Recetas de MJ · Receta de Refika Birgül · Página web recuperada desde Evernote · 3-4 dürüms",
    "author": "Refika Birgül",
    "type": "Pollo",
    "family": "Carnes y aves",
    "servings": "3-4 dürüms",
    "time": "1 noche de congelación + preparación final",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "Para El Dürüm: 2 tortillas de trigo grandes",
      "Para El Dürüm: 2 pechugas (500 g) de pollo",
      "Para El Dürüm: Lechuga iceberg",
      "Para El Dürüm: Cebolla morada",
      "Para El Dürüm: Zanahoria",
      "Para El Dürüm: Col lombarda",
      "Para El Dürüm: Tomate pera",
      "Para El Dürüm: Pepinillos en vinagre",
      "Para El Macerado: 1 cebolla",
      "Para El Macerado: 2 cucharadas soperas de yogur griego",
      "Para El Macerado: 4 cucharadas de postre de tomate concentrado",
      "Para El Macerado: 1 cucharadita de sal",
      "Para El Macerado: 2 cucharadas soperas de orégano seco",
      "Para El Macerado: 1 cucharadita de comino en polvo",
      "Para El Macerado: 1 cucharadita de pimienta negra",
      "Para El Macerado: 1 cucharadita de mantequilla punto pomada",
      "Para La Salsa Blanca: 4 cucharadas soperas de yogur griego",
      "Para La Salsa Blanca: 2 cucharadas soperas de mayonesa",
      "Para La Salsa Blanca: Zumo de 1/2 limón",
      "Para La Salsa Blanca: 1 cucharada de aceite de oliva virgen extra",
      "Para La Salsa Blanca: 1 cucharadita de cilantro fresco",
      "Para La Salsa Blanca: 1 cucharadita de comino en polvo",
      "Para La Salsa Blanca: 1 cucharadita de ajo en polvo",
      "Para La Salsa Blanca: Pimienta negra",
      "Para La Salsa Blanca: Sal",
      "Para La Salsa Roja: 2 cucharadas soperas de yogur griego",
      "Para La Salsa Roja: 1 cucharada sopera de pasta de pimiento picante",
      "Para La Salsa Roja: 1 cucharadita de jengibre fresco rallado",
      "Para La Salsa Roja: 1 cucharada de postre de vinagre",
      "Para La Salsa Roja: Chile en escamas",
      "Para La Salsa Roja: Pimienta negra",
      "Para La Salsa Roja: Sal",
      "Para El Hummus: 200 g de garbanzos cocidos",
      "Para El Hummus: 1 ajo",
      "Para El Hummus: Una pizca de sal",
      "Para El Hummus: 3 cucharadas de postre de tahini",
      "Para El Hummus: Zumo de 1/2 limón",
      "Para El Hummus: 15 g de aceite de oliva virgen extra",
      "Para El Hummus: 3 cubitos de hielo",
      "Para El Hummus: Sumac",
      "Para El Hummus: Perejil fresco",
      "Para El Hummus: Picos de pan"
    ],
    "steps": [
      "Tritura 1 cebolla muy fina y cuélala. Para el macerado solo se utiliza el agua que suelta la cebolla.",
      "Mezcla el agua de cebolla con 2 cucharadas de yogur griego y 4 cucharadas de postre de tomate concentrado.",
      "Añade 1 cucharadita de sal, 2 cucharadas de orégano seco, 1 cucharadita de comino, 1 cucharadita de pimienta negra y 1 cucharadita de mantequilla en punto pomada. Mezcla hasta obtener una pasta.",
      "Afina las pechugas de pollo: colócalas entre dos papeles y golpéalas para dejarlas lo más finas posible.",
      "Introduce los filetes en el macerado y mezcla bien para que todo el pollo quede completamente cubierto.",
      "Extiende un trozo de film transparente y coloca encima los filetes formando capas. Sitúa cada nueva capa en sentido contrario a la anterior.",
      "Enrolla el conjunto con el film formando un rulo compacto, apretando bien los extremos para que no se salga el pollo.",
      "Envuelve además el rulo con papel vegetal para evitar que se abra y déjalo en el congelador hasta el día siguiente.",
      "Prepara la salsa blanca: mezcla 4 cucharadas de yogur griego, 2 cucharadas de mayonesa, el zumo de 1/2 limón, 1 cucharada de AOVE, cilantro o eneldo picado, sal, pimienta negra, 1 cucharadita de comino y 1 cucharadita de ajo en polvo. Reserva en la nevera.",
      "Prepara la salsa roja: mezcla 2 cucharadas de yogur griego, 1 cucharada de pasta de pimiento picante, sal, 1 cucharadita de jengibre fresco rallado, pimienta negra, chile en escamas y 1 cucharada de postre de vinagre. Reserva en la nevera. Si no encuentras pasta de pimiento, la fuente propone sustituirla por 1 cucharada de pimiento asado triturado y 1 chile pequeño.",
      "Al día siguiente, saca el rulo de pollo del congelador y córtalo todavía congelado en tiras muy finas, con cuchillo o mandolina.",
      "Calienta una sartén con un chorrito de AOVE a fuego medio-alto. Cocina las tiras de pollo por ambas caras; al ser muy finas se hacen rápidamente. Retíralas a un plato y continúa por tandas hasta cocinar la cantidad necesaria.",
      "Prepara las verduras para el montaje: corta la lechuga iceberg muy fina, la cebolla morada y la col lombarda en juliana, ralla la zanahoria, corta el tomate en dados y los pepinillos en tiras.",
      "Coloca una tortilla grande sobre papel de aluminio y pinta una franja de salsa roja en el centro, sin llegar a los bordes.",
      "Añade sobre la salsa una cantidad generosa de lechuga y, a continuación, cebolla morada, zanahoria rallada, col lombarda, tomate y pepinillos.",
      "Incorpora una buena cantidad de pollo y salsea al gusto con la salsa blanca.",
      "Dobla los extremos de la tortilla y enrolla el dürüm, ayudándote con el papel de aluminio para apretarlo bien.",
      "Antes de servir, calienta el dürüm en una sartén por todos los lados para que la tortilla se ablande ligeramente.",
      "Para el hummus de acompañamiento, lava bien 200 g de garbanzos cocidos y tritúralos con 1 diente de ajo, sal, el zumo de 1/2 limón, 3 cucharadas de tahini y 15 g de AOVE.",
      "Cuando los garbanzos estén triturados, añade 3 cubitos de hielo y continúa triturando hasta obtener la textura deseada.",
      "Sirve el hummus espolvoreado con sumac y termina con un chorrito de AOVE y perejil fresco picado."
    ],
    "presentation": "Sirve el dürüm recién montado y ligeramente calentado en sartén. El hummus de la fuente puede servirse como acompañamiento.",
    "tips": "",
    "notes": "",
