    "title": "Empanadillas de carne al horno",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Empanadilla",
    "family": "Masas, panes y bollería",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Probada · Excelente",
    "ingredients": [
      "Para el relleno:",
      "1 cebolla pequeña partida en cuartos",
      "2 zanahorias peladas y cortadas en trozos",
      "40 gr de aceite de oliva virgen extra",
      "400 gr de carne picada de ternera y cerdo",
      "Sal y pimienta al gusto",
      "Un puñadito de orégano seco",
      "150 gr de tomate frito",
      "1 huevo duro picadito",
      "Necesitarás:",
      "16 obleas de empañadillas",
      "1 huevo batido para pincelar"
    ],
    "steps": [
      "Pon en el vaso la cebolla en cuartos, la zanahoria en trozos y el aceite y trocea 5 segundos en velocidad",
      "",
      "Programa 10 minutos, 120ºC o Varoma, velocidad",
      "Vierte la carne, la sal y la pimienta y el orégano y mezcla con la espátula.",
      "Reparte la carne por el vaso deshaciendo los pegotes que puedan formarse y programa 10 minutos, 120ºC o Varoma, velocidad",
      "",
      "Añade el tomate frito y mezcla 30 segundos en velocidad",
      "Comprueba el punto de sal.",
      "Retira el relleno, mezcla con el huevo duro y espera a que enfríe antes de rellenar las obleas de empanadillas.",
      "Para rellenar las obleas : Bate un huevo, y para sellar bien la oblea pinta el borde circular con huevo batido .",
      "Pon en el relleno en el centro, dobla la oblea y sella los bordes con la ayuda de un tenedor.",
      "Pon cada empanadilla sobre una bandeja de horno forrada con papel de hornear o silpaf y pincela la superficie total de cada empanadilla también por fuera y hornea a 180ºC con calor arriba y abajo, durante 20 minutos .",
      "Listo.",
      "Toni Merino"
    ],
