    "record_type": "recipe",
    "title": "Escudella catalana tradicional",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Escudella",
    "family": "Sopas, cremas y gazpachos",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "400 g espalda de ternera",
      "2",
      "zanahorias",
      "1",
      "nabo",
      "1",
      "puerro",
      "0,25",
      "coles",
      "12",
      "galets de pasta",
      "2 Ramitas perejil",
      "aceite de oliva",
      "sal",
      "pimienta"
    ],
    "steps": [
      "Lava las verduras, pélalas y córtalas en cuadraditos, reservando las peladuras y recortes para elaborar el caldo.",
      "Dispón la carne en una olla, añade las pieles de verdura y una pizca de sal y lleva a ebullición.",
      "Retira la espuma de la superficie y cuece durante 1 hora a fuego lento.",
      "Retira la carne de la olla y deja enfriar en la nevera.",
      "Cuela el caldo, llévalo a ebullición y cuece las caracolas hasta que estén al dente.",
      "Escúrrelas y deja que se enfríen.",
      "Cuece los daditos de verdura en el mismo caldo hasta que estén tiernos.",
      "Corta la carne en daditos y mezcla con las verduras.",
      "Añade el perejil picado, sal, pimienta y un poco de aceite y mezcla bien.",
      "Rellena las caracolas con la preparación y disponlas en una fuente refractaria.",
      "Caliéntalas en el horno, precalentado a 180°, durante unos 5 minutos.",
      "Distribuye las caracolas rellenas en los platos y sírvelas con el caldo restante bien caliente."
    ],
