    "id": "rtm-0083",
    "record_type": "recipe",
    "title": "Escudella i carn d'olla de Nadal",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Escudella",
    "family": "Sopas, cremas y gazpachos",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "INGREDIENTS:",
      "1 tros de costella de vedella",
      "1 punta de costella de xai (brot del pit)",
      "2 botifarres negres",
      "2 botifarres blanques",
      "2 talls de cansalada viada",
      "1 careta de porc",
      "1 tros de cua o d'os d'espinada",
      "1 tros d'os de pernil",
      "1 quarter de gallina o de pollastre",
      "4 patates",
      "2 pastanagues",
      "1 branca d'api",
      "1 xirivia / nap",
      "1 porro",
      "1 grapat de cigrons remullats",
      "1/2 col",
      "300 g de galets de Nadal",
      "sal",
      "aigua",
      "farina",
      "Per a la pilota:",
      "150 g de carn de porc picada",
      "150 g de carn de vedella picada",
      "1 gra d'all trinxat",
      "una mica de julivert picat",
      "sal",
      "pebre",
      "farina de galeta o molla de pa",
      "llet",
      "VARIANTS:",
      "Enlloc de cigrons s'hi poden posar mongetes",
      "Podeu posar cigrons crus remullats la nit anterior a l'inici de la cocció",
      "Es pot posar canyella en pols a la pilota",
      "La sopa es pot fer amb macarrons o amb arròs i/o fideus",
      "Per Nadal, de vegades es farceixen els galets per la sopa",
      "Es poden afegir mandonguilles a la sopa",
      "Es pot afegir un tros de sagí enfarinat al caldo",
      "A la sopa de fideus i arròs s'hi poden posar unes fulles de col escaldades",
      "S'hi pot afegir oca",
      "Les crestes, els pedrers, els colls, les potes i altres menuts també es poden fer bullir amb la resta de carn d'olla.",
      "La sang i el fetge del pollastre es poden afegir a la sopa tallats a daus i fregits",
      "Hi ha qui posa a sobre de la tapa un plat amb aigua i mongetes seques, quan les mongetes s'arruguen, les pela i les afegeix a l'olla",
      "Es poden afegir pinyons a la pilota",
      "Es poden coure els galets amb aigua i sal, deixant-los una mica grenyats, i afegir-los al caldo 5 minuts abans."
    ],
    "steps": [
      "Preparem tota la carn menys la carn picada. La rentem bé.",
      "Ara, en una cassola fonda i ben gran, hi posarem una bona quantitat d'aigua i ja podem engegar el foc. Anirem incorporant la carn, com aquest quart de gallina (sense pell).",
      "Un tros de cua de vedella. Un tros de cansalada viada ( o del coll, si us agrada més).",
      "Una mica de carcassa de pollastre, si és ecològic millor. Un tros de costella de vedella.",
      "Un tros de carn de vedella. Una mica de careta, en aquest cas morro.",
      "Un os de pernil, dels que fan el caldo blanc. Un altre os de pernil normal, que a mi m'agrada la seva carn.",
      "Un parell d'ossos de vedella (d'espinada). Anirem preparant tota la verdura, ben neta també.",
      "Eps!....un ratolí a la cuina! Ah!, no, és un nap!, jeje...què tonto que sóc!",
      "Doncs vinga, ja tenim la verdura ben neta i lliure d'arrels. Sobretot el porro, que quedi net, que sempre té molta sorra.",
      "I aquesta verdura l'anirem incorporant al caldo. Hi ha qui prefereix deixar coure la carn un hora i, a continuació afegir-hi la verdura.",
      "Jo ho poso tot junt i el resultat és pràcticament el mateix. La diferència es que la verdura es cou més estona i es pot desfer una mica Ho podeu comprovar a la recepta original del CPCC , que també trobareu en aquest blog, com us indico a la introducció d'aquesta recepta.",
      "Hi posem la xirivia... ...i el nap.",
      "La pastanaga. Un parell de fulles d'api.",
      "I ara si, ho cobrirem tot d'aigua. Habitualment, faig servir uns 8 litres d'aigua per aquestes quantitats de producte.",
      "Tindreu caldo per a 10 persones tranquil·lament i si en sobra, el congeleu, per consumir més endavant o per utilitzar en altres receptes. Deixem que lentament vagi fent, a foc mig-baix.",
      "Heu de respectar un marge per deixar bullir l'aigua. Més o menys jo tinc aquesta referència.",
      "Si hi poseu més aigua podria vesar. Mentre es va fent el caldo, anirem netejant els ingredients que incorporarem durant l'última mitja hora de cocció, com és la col.",
      "Netegeu-la bé. Podeu treure el tronc central si voleu, de textura no gaire agradable.",
      "Prepararem la botifarra negra, la blanca, el xoriço, les patates pelades i els cigrons si ja són bullits. Si els cigrons els heu posat en remull el dia anterior, els haureu d'incorporar a l'olla quan porti una hora de cocció, ja que necessiten el seu temps (una hora mínim).",
      "Si ja són cuits, afegiu-los durant l'última mitja hora de cocció, o es desfarien. Seguidament, anirem preparant la carn picada per fer la pilota i farcir els galets de Nadal."
    ],
    "presentation": "Servir según se indica en la fuente; si no se especifica, presentación no indicada.",
