    "title": "Fideuà de calamares, gambas y almejas",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Fideuà",
    "family": "Pastas y fideos",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "200 gr de almejas pequeñas.",
      "200 gr de gambas arroceras.",
      "80 ml de aceite de oliva virgen extra.",
      "500 ml de agua.",
      "150 gr de pimiento rojo.",
      "150 gr de pimiento verde.",
      "150 gr de cebolla.",
      "2 dientes de ajo.",
      "150 gr de tomate natural triturado.",
      "200 gr de calamares en trozos.",
      "1 pastilla de caldo de pescado.",
      "Azafrán en pelo.",
      "1 cucharadita pequeña de sal.",
      "250 gr de fideos de fideuá."
    ],
    "steps": [
      "En primer lugar, pon las almejas a remojo en agua con sal durante un mínimo de 30 minutos.",
      "Mientras tanto, pela las gambas y reserva los cuerpos.",
      "Pon en el vaso de la thermomix las cáscaras y cabezas de las gambas junto con 30 gr de aceite y rehoga 5 minutos, varoma, velocidad",
      "Agrega el agua y programa 7 minutos, varoma, velocidad",
      "Cuela el fumet del vaso con un colador y reserva el líquido (tira las cáscaras).",
      "Lava el vaso y la tapadera.",
      "Pon en el vaso de la thermomix los otros 50 ml de aceite, el pimiento rojo y verde, la cebolla y los dientes de ajo y trocea 4 segundos a velocidad",
      "Agrega ahora el tomate, pon la tapadera y sitúa el recipiente varoma en su posición con las almejas aclaradas en agua templada.",
      "Programa 10 minutos, varoma y velocidad",
      "Ve retirando las almejas según se abran y reserva.",
      "Pon ahora los cuerpos de las gambas en el recipiente varoma y colócalo en su posición.",
      "Pasado el tiempo, agrega los calamares al vaso y programa 5 minutos, varoma, giro a la izquierda y velocidad cuchara. (cuando hayan pasado 3-4 minutos, retira el recipiente varoma).",
      "Reserva los cuerpos de las gambas.",
      "Incorpora el fumet reservado, la pastilla de caldo, la sal y el azafrán.",
      "Programa 7 minutos, varoma, giro a la izquierda y velocidad",
      "Agrega los fideos de fideuá y programa unos 8-9 minutos, 100ºC, giro a la izquierda y velocidad",
      "Finalmente, agrega los cuerpos de las gambas y las almejas, mezcla delicadamente y vuelca en una fuente.",
      "Deja reposar unos 5 minutos antes de tomar."
    ],
