    "id": "rtm-0093",
    "record_type": "recipe",
    "title": "Fricandó de ternera y boletus",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Fricandó",
    "family": "Carnes y aves",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "8 filetes de llata de ternera",
      "c/n de sal",
      "c/n de pimienta negra recién molida",
      "c/n de harina",
      "1 cebolla de Figueras",
      "2 dientes de ajo",
      "50 gramos de passata o 2 tomates pera grandes y maduros",
      "1 bouquet garni",
      "150 ml de vino blanco o rancio",
      "60 gramos de boletus laminados deshidratados",
      "400-500 gramos de agua (incluye la del agua de remojo de las setas)",
      "30 gramos de avellanas tostadas",
      "30 gramos de almendras tostadas",
      "1 galleta María o 3 colines de pan",
      "c/n de aceite de oliva virgen extra",
      "c/n de sal."
    ],
    "steps": [
      "Salpimenta la carne y enharínala por los dos lados.",
      "Pon una cazuela o una sartén amplia a calentar con un fondo de aceite de oliva virgen extra, y fríe la carne para dorarla por los dos lados, entonces retírala y resérvala en un plato.",
      "Retira un poco de aceite de la cazuela si es necesario y prepara un sofrito con la cebolla picada en brunoise, el ajo laminado y la passata, al ser una pasta de tomate , apenas necesitará cocinarse para evaporar el agua.",
      "Si utilizas tomates frescos, incorpóralos rallados y cocina hasta que el tomate reduzca.",
      "A continuación reincorpora la carne a la cazuela y añade el bouquet garni , el vino blanco, los boletus previamente rehidratados en agua, el agua, un poco de sal y lleva a ebullición.",
      "Mientras tanto, pica en el mortero los frutos secos con la galleta o los colines e incorpóralos a la cazuela.",
      "Se puede añadir un poco de azúcar por la acidez del tomate si no se pone galleta.",
      "Cocina a fuego lento con la cazuela tapada durante unos 40 minutos, hasta que la carne esté bien tierna y con una salsa espesa y brillante."
    ],
    "presentation": "Servir según se indica en la fuente; si no se especifica, presentación no indicada.",
    "tips": "Se conservan los tiempos, temperaturas, reposos y advertencias incluidos en la preparación original. Conservación no especificada; pendiente de confirmar.",
