    "id": "rtm-0094",
    "record_type": "recipe",
    "title": "Fricandó de vedella amb bolets",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Fricandó",
    "family": "Carnes y aves",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "1,2 kg de llata de vedella",
      "1 ceba mitjana",
      "1/2 porro",
      "1/4 de pastanaga",
      "2 tomàquets madurs",
      "200 g de bolets variats",
      "1 got de vi ranci",
      "brou de carn",
      "pebre negre mòlt",
      "farina",
      "sal",
      "oli d'oliva",
      "Per a la picada:",
      "2 alls",
      "10 g d'ametlles torrades",
      "10 g d'avellanes torrades",
      "1 llesca de pa",
      "julivert fresc"
    ],
    "steps": [
      "Per començar, talleu la vedella a talls prims, saleu-la, enfarineu-la i fregiu-la en una cassola amb oli abundant.",
      "Quan estigui ben rossa, retireu-la i reserveu-la.",
      "A continuació, retireu l'excés d'oli de la cassola i sofregiu-hi la ceba, la pastanaga i el porro tot ben picat.",
      "Quan estiguin dauradets, afegiu-hi el tomàquet, ja pelat i sense llavors, i el vi ranci i deixeu-ho coure durant uns 10 minuts.",
      "Després, poseu-hi la vedella i el brou i deixeu-ho coure tot junt a foc suau durant 45 minuts.",
      "Mentrestant, en una paella amb una mica d'oli salteu els bolets tallats a trossos i salats.",
      "Per fer la picada, poseu en un bol els alls, les avellanes, les ametlles, el pa i el julivert i tritureu-ho bé amb el morter.",
      "Seguidament, afegiu-hi una mica del suc de la cocció de la vedella i remeneu-ho bé.",
      "Tot seguit, poseu els bolets i la picada a la cassola de la vedella, rectifiqueu-ho de sal i pebre i deixeu-ho coure durant 10 minuts més.",
      "I per acabar, deixeu reposar el fricandó una estona i ja el podeu emplatar."
    ],
    "presentation": "Servir según se indica en la fuente; si no se especifica, presentación no indicada.",
