    "id": "rtm-0095",
    "record_type": "recipe",
    "title": "Galleta de Nutella y coco en microondas",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Galleta",
    "family": "Pastelería y repostería",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "Galleta sin huevo",
      "45 gramos (3 c/s) de harina",
      "30 gramos (2 c/s) de copos de avena",
      "1 c/s de azúcar moreno",
      "1 c/s c/s de azúcar blanquilla",
      "25 gramos de aceite de coco",
      "una pizca de sal",
      "100 gramos de Nutella.",
      "Galleta con huevo",
      "45 gramos (3 c/s) de harina",
      "30 gramos de copos de avena",
      "1 c/s de azúcar moreno",
      "2 c/s de azúcar blanquilla",
      "25 gramos de aceite de coco",
      "1 huevo P",
      "una pizca de sal",
      "65 gramos de Nutella."
    ],
    "steps": [
      "Pon en un cuenco la harina, los copos de avena, el azúcar moreno y el azúcar blanquilla.",
      "Funde el aceite de coco en el microondas e incorpóralo a los ingredientes anteriores.",
      "Añade también la pizca de sal, el huevo (si corresponde) y la Nutella u otra crema de cacao y avellanas.",
      "Mezcla bien con la cuchara, obtendrás una masa densa pero no como para poder darle forma con las manos, así que se debe verter en el plato volcando el cuenco, pero es fácil darle forma redonda.",
      "Cubre un plato apto para microondas con papel vegetal y vierte la masa, déjala con un grosor de un centímetro o menos, e introduce el plato en el microondas a 800w y programa 2 minutos, pueden ser necesarios 20 o 30 segundos más, dependiendo del microondas, del grosor de la masa.",
      "Cuando retires el plato del microondas la masa estará blanda, pero no la toques, sólo déjala enfriar, entonces se endurecerá, aunque cabe señalar que la galleta con huevo queda algo tierna y la galleta sin huevo queda crujiente.",
      "Una vez fría puedes trocear la galleta y servirla en el centro de la mesa para compartirla, o tomar un trozo y el resto guardarlo para otro momento. ¡Buen provecho!"
    ],
    "presentation": "Servir según se indica en la fuente; si no se especifica, presentación no indicada.",
    "tips": "Se conservan los tiempos, temperaturas, reposos y advertencias incluidos en la preparación original. Conservación no especificada; pendiente de confirmar.",
