    "title": "Helado de fresas",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Helado",
    "family": "Postres helados y fríos",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "500 g de fresas maduras y limpias",
      "200 g de azúcar",
      "50 g de azúcar invertido",
      "2 yemas de huevo",
      "250 g de nata",
      "200 g de leche",
      "15 ml de extracto puro de vainilla"
    ],
    "steps": [
      "Pon la leche y la vainilla a hervir.",
      "Bate las yemas con el azúcar hasta que estén bien espumosas.",
      "Vierte poco a poco la leche caliente sobre las yemas y mezcla con varillas.",
      "Añade el azúcar invertido.",
      "Devuelve la mezcla al fuego y cuece a fuego suave hasta que espese ligeramente.",
      "Deja enfriar las natillas.",
      "Limpia y lava las fresas y tritúralas hasta obtener un puré.",
      "Cuando las natillas estén frías, mézclalas con la nata líquida y el puré de fresas hasta integrar bien.",
      "Pasa la mezcla a la heladora durante el tiempo indicado por la máquina. Si no tienes heladora, pásala a un recipiente y congela.",
      "Según la fuente, no es necesario remover periódicamente porque el azúcar invertido ayuda a evitar la cristalización."
    ],
    "presentation": "Servir según se indica en la fuente; si no se especifica, presentación no indicada.",
