    "id": "rtm-0102",
    "record_type": "recipe",
    "title": "Hojaldre de manzana",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Hojaldre dulce",
    "family": "Pastelería y repostería",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "1 plancha de hojaldre",
      "1 tarro de mermelada de",
      "melocotón",
      "2 manzanas",
      "10 gr de azúcar",
      "Para la crema pastelera",
      "500 ml. de leche",
      "6 huevos pequeños",
      "125 gr. de azúcar",
      "50 gr. harina de maíz - 1 rama de canela",
      "1 rama de vainilla",
      "Corteza de limón"
    ],
    "steps": [
      "Calentar la mermelada de melocotón.",
      "Cuando comience a hervir, pasarla por un colador y dejarla en forma líquida.",
      "Calentar la leche con una rama de canela, otra de vainilla y un trozo de corteza de limón.",
      "Retirar cuando comience a hervir.",
      "Separar las claras de las yemas y añadir el azúcar a éstas últimas.",
      "Batir hasta que la mezcla adquiera un color claro.",
      "Añadir entonces la harina poco a poco, e integrarlo todo.",
      "Luego incorporar la leche, primero una cuarta parte y después el resto.",
      "Remover y poner a calentar la crema en una cazuela.",
      "No dejar de remover en ningún momento para que no se pegue y cuando comience a espesar, retirarla del fuego y dejarla enfriar.",
      "Estirar el hojaldre en una superficie enharinada, pintar los laterales con huevo batido y colocar la crema pastelera en el centro de la masa ayudándonos de una manga en la que hemos introducido la crema pastelera, una vez fría.",
      "Descorazonar las manzanas y después, pelarlas y cortarlas en forma de media luna.",
      "Colocar las manzanas encima de la crema, cubrir con un poco de azúcar y hornear a 200o durante 20-25 minutos.",
      "Una vez fuera del horno, dejar enfriar y finalmente cubrir las manzanas con la mermelada líquida de melocotón."
    ],
    "presentation": "Servir según se indica en la fuente; si no se especifica, presentación no indicada.",
