    "title": "Galletas de chocolate blanco",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Galleta",
    "family": "Pastelería y repostería",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "125 gr de mantequilla en punto pomada",
      "150 gr de azúcar",
      "75 gr de azúcar moreno",
      "1 huevo",
      "150 gr de harina normal",
      "50 gr de harina de fuerza",
      "1 cucharadita de bicarbonato",
      "1/2 cucharadita de levadura Royal",
      "una pizca de sal",
      "200 gr de chocolate blanco troceado."
    ],
    "steps": [
      "Precalentamos el horno a 180º con calor arriba abajo .",
      "Batimos la mantequilla, el azúcar normal y el azúcar moreno hasta conseguir una crema suave.",
      "Agregamos el huevo y removemos hasta que se integre completamente.",
      "Añadimos las harinas, el bicarbonato, la levadura y la pizca de sal.",
      "Mezclamos totalmente y unimos al chocolate blanco troceado.",
      "Nos enharinamos las manos, formamos bolitas de masa , del tamaño de una nuez o un poco más grandes, y las colocamos en una bandeja antiadherente, o bien sobre una bandeja normal forrada con papel de horno.",
      "Las separamos unas de otras ya que la masa se expandirá bastante durante el horneado.",
      "Horneamos las galletas durante unos 12 minutos , hasta que estén ligeramente doradas.",
      "Saca la bandeja del horno y deja reposar las galletas 5 min antes de pasarlas a una rejilla para que se enfríen completamente."
    ],
