    "status": "Pendiente de hacer",
    "ingredients": [
      "3 berenjenas",
      "1 cebolleta",
      "2 dientes de ajo",
      "1 cucharada de zumo de limón",
      "8 rebanadas de pan de molde",
      "2 claras de huevo",
      "aceite de oliva virgen extra",
      "30 g de semillas de sésamo",
      "40 g de pipas de calabaza",
      "15 g de nueces peladas",
      "1/2 cucharadita de comino en polvo",
      "pimienta",
      "sal",
      "hojas de perejil"
    ],
    "steps": [
      "Unta una bandeja de horno con aceite.",
      "Corta las berenjenas y la cebolleta por la mitad.",
      "Colócalas sobre la bandeja dejando la parte de la piel hacia arriba y agrega los ajos sin pelar.",
      "Sazona, riega todo con un buen chorro de aceite y ásalos a 190ºC durante 30 minutos.",
      "Cuando se enfríen, pela los ajos, la cebolleta y las berenjenas.",
      "Trocéalos y colócalos en una jarra.",
      "Casca las nueces, trocéalas y añádelas.",
      "Agrega también un par de cucharadas de aceite, unas gotas de zumo de limón y el comino.",
      "Salpimienta y tritura con la batidora eléctrica hasta conseguir una pasta fina.",
      "Coloca las rebanadas de pan sobre una hoja de papel de horno, úntalas con las claras batidas, espolvoréalas con las pipas de calabaza y las semillas de sésamo.",
      "Cúbrelas con otro papel de horno y estíralas con un rodillo.",
      "Tuéstalas en el horno 190ºC hasta que se doren.",
      "Sirve el hummus con el pan y adorna con unas hojas de perejil."
    ],
