      "30 g de zumo de limón.",
      "2 dientes de ajo.",
      "30 g de aceite de oliva virgen extra, y un poco más para servir.",
      "150 g de pimientos del piquillo escurridos.",
      "1 cucharadita de sal.",
      "1 pellizco de pimienta molida.",
