      "Pon en el vaso el sésamo y el comino y tritura 30 s · velocidad 10.",
      "Baja los ingredientes hacia el fondo del vaso con la espátula y tritura 10 s · velocidad 9.",
      "Añade los garbanzos, el zumo de limón, los ajos, el aceite, los pimientos del piquillo, la sal y la pimienta. Tritura 15 s · velocidad 9.",
