    "id": "rtm-0113",
    "record_type": "technique",
    "title": "Jugo de carne",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Jugo de carne",
    "family": "Técnicas y bases culinarias",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "2 l de fondo o caldo oscuro de ternera",
      "100 ml de brandy o coñac",
      "200 ml de vino (el tipo depende de la salsa deseada: ver notas)",
      "750 g de recortes de la carne que se va a servir o en su defecto",
      "carne de segunda cortada en trozos pequeños",
      "300 g de huesos de vacuno",
      "300 g de verduras (zanahoria",
      "cebolla) picadas",
      "1 cs de aceite de oliva",
      "sal y pimienta"
    ],
    "steps": [
      "Sofreír todos los ingredientes con el aceite en una olla hasta que tomen un buen color dorado.",
      "Añadir el caldo o fondo oscuro, el licor y el vino.",
      "Llevar a ebullición, bajar el fuego y cocer 2 horas a fuego muy lento.",
      "Colar el jugo resultante y pasarlo a un cazo limpio.",
      "Llevar a ebullición y cocer unos minutos espumando hasta eliminar las impurezas y grasa lo mejor posible.",
      "Si está muy claro, será necesario espesarlo: a) con 20 g de maicena disuelta en un poco de agua o caldo fríos.",
      "Se añade fuera del fuego, se mezcla bien y se cuece hasta que espese y vuelva a estar transparente. b) con mantequilla amasada.",
      "Se mezcla 1 ct de harina con igual cantidad de mantequilla fría y se amasa.",
      "Se añade a la salsa caliente, pero sin hervir, a trocitos. cuando todo esté bien disuelto, se calienta suavemente hasta que espese. c) por reducción: cocer hasta que se reduzca y se vaya espesando hasta quedar con la textura requerida.",
      "Si la salsa es para mucha gente no lo aconsejo, pues se queda en nada.",
      "Si se va a utilizar este sistema es preciso tener mucho cuidado con la sal, poner nada o muy poca al principio, para que no quede demasiado salado al concentrarse.",
      "Probar y sazonar con sal y pimienta si es necesario."
    ],
