    "title": "Lacón fresco asado",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Cerdo",
    "family": "Carnes y aves",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "1 lacón de cerdo fresco",
      "4 dientes de ajo",
      "unas ramas de perejil",
      "200 ml de vino blanco",
      "120 ml de aceite de oliva",
      "1/2 cucharadita de pimentón",
      "orégano seco",
      "6 clavos",
      "sal gruesa"
    ],
    "steps": [
      "Comenzaremos adobando la noche anterior nuestro lacón .",
      "Para ello en el vaso de una batidora echaremos los dientes de ajo , el orégano, el vino, el aceite, el pimentón y el perejil picado.",
      "Trituramos hasta formar un adobo.",
      "Con un cuchillo bien afilado damos unos cortes a la piel del lacón haciendo forma de rombos, esto facilitará el asado.",
      "Salamos con sal gruesa todo el lacón frotándolo bien para que la sal entre en la carne.",
      "Lo adobamos por ambos lados con el adobo preparado anteriormente, le colocamos los clavos en los cortes de la piel y lo dejamos en una fuente tapado con film hasta el día siguiente o un mínimo de ocho horas.",
      "Precalentamos el horno a 180 grados, colocamos una bandeja de horno y le añadimos agua para que cubra toda la base de la bandeja.",
      "Colocamos una rejilla encima y en ella disponemos el lacón con la piel hacia arriba.",
      "Hornea durante unas 2 h 30 min."
    ],
