      "En la misma sartén añade un poco más de aceite. Lava y pica finamente la parte blanca del puerro y póchala durante unos 8 min; sala ligeramente.",
      "Añade la almendra en granillo y rehoga brevemente.",
      "Corta las ciruelas pasas en dados, incorpóralas y rehoga el conjunto.",
      "Vierte la leche evaporada, salpimienta y deja reducir hasta que la salsa espese ligeramente.",
      "Devuelve el lomo reservado a la sartén, apaga el fuego y sirve."
