    "id": "rtm-0124",
    "record_type": "recipe",
    "title": "Helado de vainilla con cookies de chocolate",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Helado",
    "family": "Postres helados y fríos",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "500 gramos de leche",
      "5 yemas de huevo",
      "100 gramos de azúcar",
      "1 vaina de vainilla (las semillas del interior)",
      "200 gramos de nata 35-38% M.G.",
      "60 gramos de azúcar invertido",
      "150 gramos de cookies o galletas de chocolate (pueden ser Oreo sin relleno)",
      "30-50 gramos de pepitas de chocolate."
    ],
    "steps": [
      "Prepara una crema inglesa: pon en el vaso la leche, las yemas, el azúcar y las semillas de vainilla y programa 8 min · 90 °C · velocidad 4. Si la haces a mano, calienta los mismos ingredientes sin dejar de batir y sin que lleguen a hervir, hasta que la crema nape el dorso de una cuchara.",
      "Si quieres hacerla a mano, pero de forma rápida en un cazo, pon todos los ingredientes indicados en él y sin dejar de batir con unas varillas, llévalo al fuego, deja que se caliente bien y sin llegar a hervir, cuece hasta que espese ligeramente, la crema debe napar el dorso de la cuchara.",
      "Deja enfriar la crema inglesa a temperatura ambiente (antes puedes añadir, si lo deseas, unas pepitas de chocolate, pero no remuevas), después añade la nata y el azúcar invertido, e introduce este preparado en el frigorífico para que repose y se enfríe durante al menos cuatro horas.",
      "Si vas a hacer el helado sin heladora, incorpora las galletas troceadas y las pepitas de chocolate a la crema del helado, mezcla bien para distribuir los tropezones homogéneamente y vierte en un recipiente, preferiblemente de acero inoxidable, con tapa.",
      "Introduce el recipiente en el congelador, y cada hora aproximadamente retíralo y bate bien para reducir la formación de cristales y que el helado quede bien cremoso.",
      "Si haces el helado con heladora, ponla en marcha y después vierte la crema de vainilla por el bocal.",
      "Deja que la heladora trabaje unos 25 minutos, el helado estará más denso y voluminoso, y algo helado, entonces añade las galletas troceadas y los chips de chocolate, deja que la heladora funcione unos minutos más para que se distribuyan bien.",
      "Vierte el helado de vainilla con cookies de chocolate en un recipiente apropiado para guardarlo en el congelador y deja que termine de congelarse.",
      "Si pasan muchas horas, el helado tendrá una temperatura demasiado baja para el servicio, por lo que antes de servirlo será necesario que esté a temperatura ambiente unos diez minutos, recuerda que la temperatura de servicio de un helado puede estar en unos -12 grados centígrados."
    ],
    "presentation": "Sirve el helado en copa, vaso o cucurucho. Puede acompañarse con sirope de chocolate, barquillos o una galleta.",
    "tips": "Se conservan los tiempos, temperaturas, reposos y advertencias incluidos en la preparación original. Conservación no especificada; pendiente de confirmar.",
    "notes": "",
    "tags": [
      "Postresheladosyfríos",
      "Helado",
      "Evernote",
      "PendienteDeHacer"
    ],
    "emoji": "🍽️",
    "vegetarian": true,
    "vegan": false,
    "dietary_note": "",
    "favorite": false,
    "source_trace": "Fuente: Helado de vainilla con cookies de chocolate  Gastronom#U00eda & C#U00eda.html. URL original: http://gastronomiaycia.republica.com/2015/08/12/receta-de-helado-de-vainilla-con-cookies-de-chocolate/"
