    "title": "Tomates deshidratados al horno",
    "origin": "Página web · Transcripción normalizada",
    "author": "",
    "type": "Conserva / base",
    "family": "Técnicas y bases culinarias",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "1 kg de tomates",
      "1 1/2 cucharadita de sal marina",
      "1 cucharadita de azúcar",
      "1/2 cucharadita de orégano seco",
      "1/2 cucharadita de albahaca seca",
      "Aceite de oliva"
    ],
    "steps": [
      "Lava los tomates, córtalos por la mitad, ponlos en un colador con la sal y deja reposar 30 min.",
      "Calienta el horno a 220 °C. Mezcla azúcar y especias; coloca los tomates con el corte hacia arriba en una bandeja y añade la mezcla y aceite.",
      "Hornea 15 min, apaga el horno y deja 1 h. Aplasta ligeramente los tomates y déjalos 1 h más con el calor residual.",
      "Calienta de nuevo a 200 °C, hornea 5 min, apaga y deja secar 2 h.",
      "Si necesitan más secado, repite 5 min a 180 °C y deja otras 2 h. Enfría y guarda en un recipiente de vidrio cubiertos con aceite."
    ],
    "presentation": "Usar como base para bruschettas, pizzas, pasta, vinagretas o pesto.",
    "tips": "El grado de secado depende del tamaño y carnosidad del tomate. La fuente indica que pueden añadirse ajo, alcaparras y laurel al conservarlos en aceite.",
    "notes": "",
