    "record_type": "recipe",
    "title": "Garbanzos con arroz y sofrito de pimentón",
    "origin": "Página web · Transcripción normalizada",
    "author": "",
    "type": "Guiso de legumbres",
    "family": "Verduras y legumbres",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "350 g de garbanzos",
      "1 cabeza de ajos",
      "120 g de arroz",
      "1 cubito de caldo de ave concentrado",
      "Unas ramitas de perejil",
      "2 hojas de laurel",
      "Aceite de oliva virgen extra",
      "Pimentón, 2-3 cucharadas según la fuente",
      "Sal"
    ],
    "steps": [
      "La noche anterior, deja los garbanzos en remojo en un bol con agua.",
      "Al día siguiente, escúrrelos y colócalos en la olla rápida. Añade agua hasta que quede un par de dedos por encima de los garbanzos y pon a fuego medio sin tapar del todo.",
      "Mientras, maja en un mortero el ajo y el perejil con un poco de sal.",
      "Desespuma el agua de cocción para retirar impurezas y vierte la majada.",
      "Añade el cubito de caldo concentrado y cierra la olla. Cuando hayan subido los anillos, cuenta 7-8 min.",
      "Apaga y espera a que bajen completamente los anillos antes de abrir.",
      "Abre la olla, añade el arroz y mantén a fuego medio.",
      "En una sartén pequeña, calienta un chorrito de aceite de oliva virgen extra y añade 2-3 cucharadas de pimentón. Caliéntalo 1-2 min con cuidado de que no se queme y añádelo al cocido.",
      "Cuece unos 15 min con la olla destapada, hasta que se haga el arroz.",
      "Rectifica de sal al final. La fuente propone servir en un recipiente previamente templado unos minutos en el horno a 50 °C para conservar mejor el calor."
    ],
    "presentation": "Servir según la preparación original.",
