      "Añadir el azúcar, la vainilla, los huevos y mezclarlo.",
      "Añadir la harina tamizada y la levadura en polvo.",
      "Sin parar de remover, añadir la leche poco a poco.",
      "Mezclar durante 2-3 minutos al velocidad máxima con una batidora.",
      "Dejar reposar unos 15 minutos.",
      "Enchufar la gofrera, y seguir las intrucciones de la misma, poniendo una cantidad equivalente a medio cazo sopero en cada lado del aparato.",
      "Cerrarlo y poner el regulador de potencia al dos.",
      "Cuando el piloto se ponga en verde será la señal de que ya está vuestro gofre.",
      "Yo siempre los tengo un minuto más para que se queden más crujientes.",
      "Retirar con cuidado a una rejilla.",
      "Yo me ayudo de una espátula de madera, mejor que con pinzas, que lo rompen.",
      "Se levanta un poco el gofre con la espátula y con cuidado, con la espátula y un dedo a la rejilla.",
      "Servir los gofres calientes con el acompañamiento que os guste, en casa nos encantan con nata y sirope de caramelo."
