    "id": "rtm-0148",
    "record_type": "recipe",
    "title": "Hojaldres de Astorga",
    "origin": "Página web · Transcripción normalizada",
    "author": "",
    "type": "Hojaldre dulce",
    "family": "Pastelería y repostería",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "2 planchas de hojaldre fresco rectangular",
      "500 ml. de agua",
      "750 gr. de azúcar",
      "3 cucharadas de miel",
      "1 hoja de gelatina neutra",
      "Unas gotas de zumo de limón"
    ],
    "steps": [
      "Precalienta el horno a 200 °C, con calor arriba y abajo.",
      "Estira la primera plancha de hojaldre y córtala en cuadrados de aproximadamente 6 × 4 cm. Marca y vacía el centro de cada cuadrado.",
      "Corta la segunda plancha en cuadrados del mismo tamaño, esta vez sin vaciar el centro.",
      "Monta cada pieza colocando abajo un cuadrado entero y encima uno con el centro vaciado. Humedece ligeramente la primera capa con agua para ayudar a que se adhieran.",
      "Coloca las piezas en una bandeja y hornea unos 15 min, ajustando el tiempo al horno.",
      "Para el almíbar, pon en un cazo el agua, el azúcar, la miel, la gelatina y unas gotas de zumo de limón.",
      "Cuece unos 5 min a fuego fuerte y después otros 5 min a fuego medio.",
      "Glasea los hojaldres por ambas caras, sumergiéndolos aproximadamente 10 s por cada lado. No prolongues el baño para evitar que absorban demasiado almíbar y se bajen.",
      "Deja reposar los hojaldres en una bandeja. La fuente indica que mejoran de sabor al día siguiente."
    ],
    "presentation": "Servir según la preparación original.",
    "tips": "Conservación no especificada; pendiente de confirmar.",
